  ('mashou', 'sent-ex-mashou-3', 2),
  ('mashou', 'sent-ex-mashou-4', 3),
  ('tai', 'sent-ex-tai-1', 0),
  ('tai', 'sent-ex-tai-2', 1),
  ('tai', 'sent-ex-tai-3', 2),
  ('tai', 'sent-ex-tai-4', 3),
  ('kara-reason', 'sent-ex-kara-1', 0),
  ('kara-reason', 'sent-ex-kara-2', 1),
  ('kara-reason', 'sent-ex-kara-3', 2),
  ('kara-reason', 'sent-ex-kara-4', 3),
  ('ni-direction', 'sent-ex-ni-1', 0),
