ON CONFLICT (grammar_point_id, sentence_id, role) DO NOTHING;

-- The tokens, so production gets them too.
--
-- `tokenise:authored` is a dev script and production runs migrations and seeds
-- and nothing else, so this is the only way the tokens reach it. Without them
-- the quiz derivation reads an empty table and generates nothing.
DELETE FROM sentence_tokens WHERE sentence_id IN ('sent-ex-aru-1', 'sent-ex-aru-2', 'sent-ex-aru-3', 'sent-ex-aru-4', 'sent-ex-ga-1', 'sent-ex-ga-2', 'sent-ex-ga-3', 'sent-ex-ga-4', 'sent-ex-kara-1', 'sent-ex-kara-2', 'sent-ex-kara-3', 'sent-ex-kara-4', 'sent-ex-kudasai-1', 'sent-ex-kudasai-2', 'sent-ex-kudasai-3', 'sent-ex-kudasai-4', 'sent-ex-mashou-1', 'sent-ex-mashou-2', 'sent-ex-mashou-3', 'sent-ex-mashou-4', 'sent-ex-mo-1', 'sent-ex-mo-2', 'sent-ex-mo-3', 'sent-ex-mo-4', 'sent-ex-ni-1', 'sent-ex-ni-2', 'sent-ex-ni-3', 'sent-ex-ni-4', 'sent-ex-tai-1', 'sent-ex-tai-2', 'sent-ex-tai-3', 'sent-ex-tai-4', 'sent-ex-wa-1', 'sent-ex-wa-2', 'sent-ex-wa-3', 'sent-ex-wa-4', 'sent-ex-wo-1', 'sent-ex-wo-2', 'sent-ex-wo-3', 'sent-ex-wo-4');
